#!/usr/bin/env python
"""Write tables.md (per-powder tables) from results.json. Run after run_theory.py."""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
R = json.load(open(os.path.join(HERE, "results.json")))
P = list(R["powders"].keys())
out = ["# Per-powder tables (computed, not measured)", "",
       "Generated by `tables.py` from `results.json`. Powder properties are the #196 DEM references and "
       "the handbook/class values of the 12 battery powders (`literature_powder_properties.csv`, e8811bd); "
       "PSD widths and sorption classes are assumptions (see README).", ""]


def f(x, n=3):
    if x is None:
        return "-"
    if isinstance(x, bool):
        return "yes" if x else "no"
    if isinstance(x, (int, float)):
        if x == 0:
            return "0"
        if abs(x) >= 1000 or abs(x) < 0.01:
            return f"{x:.2g}"
        return f"{x:.{n}g}"
    return str(x)


def table(header, rows):
    out.append("| " + " | ".join(header) + " |")
    out.append("|" + "---|" * len(header))
    for r in rows:
        out.append("| " + " | ".join(f(v) for v in r) + " |")
    out.append("")


pw = R["powders"]

out += ["## Test 1. Heap on the pedestal (camera 35 um/px at 120 mm)", ""]
for ped in ("20mm", "30mm"):
    out.append(f"Pedestal {ped}:")
    out.append("")
    t = R["test1_aor"]["pedestals"][ped]
    table(["powder", "AoR (deg)", "height (mm)", "heap (g)", "fit SD per flank (deg)", "perspective bias (deg)", "D/d50"],
          [[p, pw[p]["aor_deg"], t[p]["h_mm"], t[p]["m_g"], t[p]["sigma_flank_analytic_deg"], t[p]["perspective_bias_deg"],
            t[p]["D_over_d50"]] for p in P])

out += ["## Test 2. Graduated cylinder (13 mm bore, fill 6 g or 8 mL)", ""]
t = R["test2_density"]["powders"]
table(["powder", "fill (g)", "H bulk (mm)", "H tapped (mm)", "poured cone (mm)", "bias if apex read (%)",
       "bias if wall read (%)", "rho_b SD (%)", "Hausner", "HR SD (%)", "Carr (%)", "Kawakita a"],
      [[p, t[p]["fill_g"], t[p]["H_bulk_mm"], t[p]["H_tap_mm"], t[p]["cone_on_top_mm"], t[p]["bias_if_apex_read_pct"],
        t[p]["bias_if_wall_read_pct"], 100 * t[p]["rho_bulk_rel_sigma"], t[p]["hausner"], 100 * t[p]["hausner_rel_sigma"],
        t[p]["carr_pct"], t[p]["kawakita_a"]] for p in P])

out += ["## Test 3. Ring normal stress (25 mm ID x 6 mm ring, lids 0 / 5 / 15 g)", ""]
t = R["test3_tilt"]["powders"]
table(["powder", "powder in ring (g)", "sigma_n lid 0 (Pa)", "lid 5 g (Pa)", "lid 15 g (Pa)", "0.5 mm shim / d90",
       "shim for 2 x d90 (mm)"],
      [[p, t[p]["lid_0g"]["m_powder_g"], t[p]["lid_0g"]["sigma_n_Pa"], t[p]["lid_5g"]["sigma_n_Pa"],
        t[p]["lid_15g"]["sigma_n_Pa"], t[p]["shim_0.5mm_over_d90"], t[p]["shim_needed_mm_(2xd90)"]] for p in P])

t = R["test3_tilt"]["ring_hang"]
table(["powder", "ring (g)", "friction capacity, no lid (g)", "5 g lid (g)", "15 g lid (g)", "carried with no lid"],
      [[p, t[p]["lid_0g"]["ring_g"], t[p]["lid_0g"]["capacity_g"], t[p]["lid_5g"]["capacity_g"], t[p]["lid_15g"]["capacity_g"],
        t[p]["lid_0g"]["carried"]] for p in P])

out += ["## Test 4. Grains needed (95 % half-width) and an imaging plan at 5 % area coverage", ""]
nn = R["test4_psd"]["N_needed"]
table(["s (ln sigma_g)", "number d50 +-2 %", "number d90 +-5 %", "volume d50 +-2 %", "volume d90 +-5 %",
       "formula, number d50", "formula, number d90", "Kish factor exp(9 s^2)"],
      [[s, v["number_d50_2pct"], v["number_d90_5pct"], v["volume_d50_2pct"], v["volume_d90_5pct"],
        v["analytic_number_d50_2pct"], v["analytic_number_d90_5pct"], v["kish_volume_factor"]] for s, v in nn.items()])
t = R["test4_psd"]["imaging_plans"]
table(["powder", "s assumed", "um/px", "field (mm)", "grains per field", "fields (number)", "fields (volume)",
       "powder to image for volume stats (mg)"],
      [[p, t[p]["s_ln_assumed"], t[p]["px_um"], f"{t[p]['field_mm'][0]:.3g} x {t[p]['field_mm'][1]:.3g}",
        t[p]["grains_per_field"], t[p]["fields_number"], t[p]["fields_volume"], t[p]["sample_mass_mg_for_volume_count"]]
       for p in P])
pm = R["test4_psd"]["pixel_sizing_mc"]
table(["grain size (px)"] + list(pm.keys()), [["SD of d (%)"] + [100 * v["sd"] for v in pm.values()],
                                              ["bias of d (%)"] + [100 * v["bias"] for v in pm.values()]])

out += ["## Test 5. Orifice cup (Beverloo C 0.58, k 1.5; 5 g fill in the 25 mm cup)", ""]
t = R["test5_orifice"]["powders"]
discs = list(next(iter(t.values()))["discs"].keys())
table(["powder", "fill height (mm)", "D jam 4.94 d50 (mm)", "Bond (Rumpf)"] + [f"W {d} mm (g/s)" for d in discs],
      [[p, t[p]["fill_height_mm_5g"], t[p]["D_jam_mm"], t[p]["bond_number_rumpf"]] +
       [t[p]["discs"][d]["W_gps_k1.5"] for d in discs] for p in P])
table(["powder", "heel at 3 mm (g)", "heel at 6 mm (g)", "steady flow at 3 mm (s)", "steady flow at 6 mm (s)",
       "samples at 10 Hz, 6 mm"],
      [[p, t[p]["discs"]["3.0"]["heel_g"], t[p]["discs"]["6.0"]["heel_g"], t[p]["discs"]["3.0"]["steady_s"],
        t[p]["discs"]["6.0"]["steady_s"], t[p]["discs"]["6.0"]["samples_10Hz"]] for p in P])
table(["no flow at (mm)", "flows at (mm)", "sigma_c range (Pa), rho_b 1000, H 2.2", "half-width of the step"],
      [[b["no_flow_mm"], b["flows_mm"], f"{b['sigma_c_Pa_rho1000_H2.2'][0]:.3g}-{b['sigma_c_Pa_rho1000_H2.2'][1]:.3g}",
        b["step_rel_half_width"]] for b in R["test5_orifice"]["sigma_c_brackets"]])

out += ["## Test 6. Expected equilibrium uptake (mg water per g dry), by class (assumed isotherms)", ""]
t = R["test6_humidity"]["uptake_mg_per_g"]
rh = [k for k in next(iter(t.values())).keys() if k != "class"]
table(["powder", "class"] + [f"{r} % RH" for r in rh],
      [[p, t[p]["class"]] + [("above DRH or hydrate change" if t[p][r] is None else t[p][r]) for r in rh] for p in t])
g = R["test6_humidity"]["greenspan"]
table(["salt", "RH at 20 C", "25 C", "30 C", "dRH/dT (%RH/K)", "+-u at 25 C (Greenspan)"],
      [[s, v["RH_20"], v["RH_25"], v["RH_30"], v["dRH_dT_per_K"], v["u25"]] for s, v in g.items()])
o = R["test6_humidity"]["offsets"]
table(["salt", "sample +0.1 K (%RH)", "+0.5 K", "+1.0 K"], [[s, v["dT_0.1K"], v["dT_0.5K"], v["dT_1.0K"]] for s, v in o.items()])
k = R["test6_humidity"]["kinetics_2mm"]
table(["layer", "dq/dRH (kg/kg per unit RH)", "porosity", "D_app (m2/s)", "t95 in a 2 mm layer (s)"],
      [[n, v["slope_per_RH"], v["eps"], v["D_app_m2s"], v["t95_s"]] for n, v in k.items()])

out += ["## Test 7. Drum speeds (40 mm, 15 mm deep)", ""]
t = R["test7_drum"]["speeds"]
table(["rpm", "Froude", "regime (Mellmann)", "deg/s", "frames per 3 deg sawtooth at 10 fps", "frames per 37 deg"],
      [[r, v["Fr"], v["regime"], v["deg_per_s"], v["frames_per_3deg_avalanche_10fps"], v["frames_per_37deg_avalanche_10fps"]]
       for r, v in t.items()])
t = R["test7_drum"]["counting_90s"]
table(["speed", "dry: avalanches in 90 s", "SE of mean (deg)", "cohesive: avalanches in 90 s", "SE of mean (deg)",
       "rel. SE of scatter", "cohesive, 300 s: avalanches", "rel. SE of scatter"],
      [[k, v["dry_3deg_sd4.4"]["avalanches"], v["dry_3deg_sd4.4"]["se_mean_deg"], v["cohesive_37deg_sd12.4"]["avalanches"],
        v["cohesive_37deg_sd12.4"]["se_mean_deg"], v["cohesive_37deg_sd12.4"]["rel_se_scatter"],
        v["cohesive_37deg_sd12.4_300s"]["avalanches"], v["cohesive_37deg_sd12.4_300s"]["rel_se_scatter"]] for k, v in t.items()])
t = R["test7_drum"]["fill"]
table(["powder", "40 % fill (g)", "D/d50"], [[p, t[p]["mass_g_40pct"], t[p]["D_over_d50"]] for p in P])

out += ["## Test 8. Janssen in the mould (20 mm x 40 mm) and self-weight", ""]
t = R["test8_ucs"]["janssen"]
table(["powder and wall", "K", "lambda (mm)", "foot at 200 Pa top (Pa)", "foot at 2 kPa top (Pa)", "foot/top at 2 kPa",
       "column mean at 2 kPa (Pa)"],
      [[n, v["K"], v["lambda_mm"], v["s0_200"]["bottom_Pa"], v["s0_2000"]["bottom_Pa"], v["s0_2000"]["bottom_over_top"],
        v["s0_2000"]["mean_Pa"]] for n, v in t.items()])
st = R["test8_ucs"]["ffc_max_standing_cohesive_ref"]
rows = []
for H in ("20", "30", "40"):
    for mu in ("0.4", "0.25", "0.15"):
        rows.append([f"H {H} mm, mu_w {mu}"] + [st[f"H{H} | mu {mu} | s0 {s0}"] for s0 in (2000, 4000, 8000)])
table(["mould", "largest ff_c that stands, 2 kPa", "4 kPa", "8 kPa"], rows)
t = R["test8_ucs"]["self_weight_Pa"]
table(["powder", "rho g H at H 40 (Pa)", "at H 20 (Pa)"], [[p, t[p]["H40"], t[p]["H20"]] for p in P])

out += ["## Test 9. Gap and layer mass on the 100 x 30 coupon (phi 0.34 dry, 0.26 cohesive)", ""]
t = R["test9_spread"]["powders"]
rows = []
for p in P:
    v = t[p]
    g1, g2 = v["gap_0.1mm"], v["gap_0.2mm"]
    gd = [kk for kk in v if kk.startswith("gap_") and kk not in ("gap_0.1mm", "gap_0.15mm", "gap_0.2mm")][0]
    rows.append([p, g1["gap_over_d50"], g2["gap_over_d50"], g1["layer_g"], g2["layer_g"], v["dem_gap_2.5d50_mm"],
                 v[gd]["layer_g"], v[gd]["feed_g_1.5x"], v["passive_force_mN"]])
table(["powder", "0.10 mm gap / d50", "0.20 mm / d50", "layer at 0.10 (g)", "layer at 0.20 (g)", "gap 2.5 d50 (mm)",
       "layer at 2.5 d50 (g)", "feed for it, 1.5x (g)", "passive force, 0.5 g line (mN)"], rows)

out += ["## Test 10. Charge levels", ""]
t = R["test10_faraday"]["signals"]
table(["q/m (C/kg)", "Q for 0.5 g (nC)", "Q for 1 g (nC)", "largest dose on 10 nF (g)", "on 100 nF (g)", "LSB / Q at 0.5 g, 10 nF"],
      [[k, v["Q_nC_0.5g"], v["Q_nC_1g"], v["max_dose_g_10nF"], v["max_dose_g_100nF"], v["rel_resolution_0.5g_10nF"]] for k, v in t.items()])
t = R["test10_faraday"]["DA"]
table(["C_f dielectric", "DA (assumed)", "false charge after full scale, 10 nF (pC)", "100 nF (pC)", "relative to 0.5 nC"],
      [[k, v["DA_assumed"], v["false_pC_after_FS_10nF"], v["false_pC_after_FS_100nF"], v["rel_to_0.5nC"]] for k, v in t.items()])
t = R["test10_faraday"]["decay"]
table(["leakage across C_f (ohm)", "tau 10 nF (s)", "loss in 202 s (%)", "tau 100 nF (s)", "loss in 202 s (%)"],
      [[k, v["tau_s_10nF"], v["loss_pct_202s_10nF"], v["tau_s_100nF"], v["loss_pct_202s_100nF"]] for k, v in t.items()])
t = R["test10_faraday"]["max_qm_breakdown_C_per_kg"]
table(["powder", "q/m at air breakdown on the grain surface (C/kg)"], [[p, t[p]] for p in P])

open(os.path.join(HERE, "tables.md"), "w").write("\n".join(out) + "\n")
print("wrote tables.md,", len(out), "lines")
